import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {

    public static List<String> groupAnagrams(List<String> words) {
        Map<String, List<String>> groups = new HashMap<>();
        for (String word : words) {
            char[] letters = word.toCharArray();
            Arrays.sort(letters);
            groups.computeIfAbsent(new String(letters), key -> new ArrayList<>()).add(word);
        }
        List<String> grouped = new ArrayList<>(groups.size());
        for (List<String> group : groups.values()) {
            Collections.sort(group);
            grouped.add(String.join(",", group));
        }
        Collections.sort(grouped);
        return grouped;
    }
}

