public class Solution {

    public static int insertionPoint(List<Integer> sorted, int key) {
        int low = 0;
        int high = sorted.size();
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (sorted.get(mid) < key) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}

