import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.TreeMap;

public class Solution {

    public static List<String> topologicalOrder(Map<String, List<String>> graph) {
        Map<String, Integer> incoming = new TreeMap<>();
        for (String node : graph.keySet()) {
            incoming.putIfAbsent(node, 0);
        }
        for (List<String> targets : graph.values()) {
            for (String target : targets) {
                incoming.merge(target, 1, Integer::sum);
            }
        }
        PriorityQueue<String> ready = new PriorityQueue<>();
        for (Map.Entry<String, Integer> entry : incoming.entrySet()) {
            if (entry.getValue() == 0) {
                ready.add(entry.getKey());
            }
        }
        List<String> order = new ArrayList<>(incoming.size());
        while (!ready.isEmpty()) {
            String node = ready.poll();
            order.add(node);
            for (String target : graph.getOrDefault(node, List.of())) {
                if (incoming.merge(target, -1, Integer::sum) == 0) {
                    ready.add(target);
                }
            }
        }
        return order.size() == incoming.size() ? order : new ArrayList<>();
    }
}

