public class Solution {

    public static int countSubarrays(List<Integer> values, int target) {
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, 1);
        int running = 0;
        int found = 0;
        for (Integer value : values) {
            running += value;
            found += seen.getOrDefault(running - target, 0);
            seen.merge(running, 1, Integer::sum);
        }
        return found;
    }
}

